import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — edge cases and base premiums", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("plain sword for a newcomer → 100 base + 10 first insurance + 5 fee = 115 G");
    it.todo("plain amulet for a newcomer → 60 + 6 + 5 = 71 G");
    it.todo("plain staff for a newcomer → 80 + 8 + 5 = 93 G");
    it.todo("plain potion for a newcomer → 40 + 4 + 5 = 49 G");
    it.todo("unknown item type (broomstick) in a quote → throws an error");
  });

  describe("quote — components and building blocks", () => {
    it.todo("2 runes → 50 G base premium (premium 50 + 5 + 5 = 60 G)");
    it.todo("3 runes → 60 G base premium, block applies (premium 60 + 6 + 5 = 71 G)");
    it.todo("4 runes → 100 G base premium, no block (premium 100 + 10 + 5 = 115 G)");
    it.todo("7 runes → 175 G base premium (premium 175 + 17.5 + 5 = 197.5 → 198 G, rounded up)");
    it.todo("2 runes + 1 moonstone → 75 G base premium, no block across types (premium 75 + 7.5 + 5 = 87.5 → 88 G)");
    it.todo("3 runes + 3 moonstones → 120 G base premium, two separate blocks (premium 120 + 12 + 5 = 137 G)");
  });

  describe("quote — item-specific modifiers", () => {
    it.todo("newcomer with cursed steel sword enchantment 3 → 165 G (100 + 50 curse + 10 first + 5 fee)");
    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies (100 + 30 + 10 + 5 = 145 G)");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge (100 + 10 + 5 = 115 G)");
    it.todo("cursed sword with enchantment 5 → both surcharges apply (100 + 50 + 30 + 10 + 5 = 195 G)");
    it.todo("cursed sword + plain amulet → curse applies only to the sword's base: 160 + 50 = 210, + 16 first + 5 fee = 231 G");
  });

  describe("quote — policy-wide modifiers", () => {
    it.todo("customer with exactly 2 years → loyalty discount applies (sword: 100 − 20 + 10 + 5 = 95 G)");
    it.todo("customer with 1 year → no loyalty discount (sword: 115 G)");
    it.todo("second quote in a scenario gets 15 % follow-up discount (newcomer sword: 100 + 10 − 15 + 5 = 100 G)");
    it.todo("long-standing customer's second contract, cursed steel sword enchantment 7 → 160 G (first insurance still applies)");
  });

  describe("claim — reimbursement rules", () => {
    it.todo("regular steel sword enchantment 3, damage 500 → payout 400 G, remaining cap 1600 G");
    it.todo("rune damaged by 200 → payout 100 G (no special clause)");
    it.todo("steel sword enchantment 9, damage 1000 → payout 400 G (50 % then deductible)");
    it.todo("dragon-material sword enchantment 9, damage 1000 → payout 400 G (50 % rule wins)");
    it.todo("dragon-material sword enchantment 5, damage 800 → payout 700 G");
    it.todo("dragon-material sword exactly enchantment 8, damage 1000 → payout 400 G");
    it.todo("payout yielding 350.5 G is rounded down to 350 G (enchantment 9, damage 901)");
  });

  describe("claim — deductible per damage event", () => {
    it.todo("dragon attack damages sword (500) and amulet (300) → payout 600 G (deductible per item)");
    it.todo("two swords insured, both damaged → each damage has its own deductible");
  });

  describe("claim — cap", () => {
    it.todo("policy with two swords → insurance sum 2000, cap 4000 (remaining cap after claim reflects it)");
    it.todo("sword + amulet → cap 3200 G");
    it.todo("cursed sword → cap 2000 G based on unmodified insurance value");
    it.todo("sword + 3 runes (block) → insurance sum 1750, cap 3500 G");
    it.todo("two successive claims of 1500 on a sword → 1400 (remaining 600), then 600 (remaining 0)");
  });

  describe("claim — invalid input", () => {
    it.todo("damage to an item not in the policy (amulet when only sword insured) → throws");
    it.todo("damage to an unknown item type → throws");
    it.todo("more damage entries of a type than items covered (two swords damaged, one insured) → throws");
    it.todo("negative damage amount (-200) → throws");
  });

  describe("scenario", () => {
    it.todo("schema example: 5-year customer quotes silver amulet then claims 200 fire damage → premium 59 G, payout 100 G, remaining cap 1100 G");
  });

  describe("CLI", () => {
    it.todo("reads scenario JSON from stdin and writes results JSON to stdout");
    it.todo("exits non-zero and writes error to stderr for unknown item type, with no results on stdout");
  });
});

