export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: unknown[];
};

export type ScenarioResult = { results: unknown[] };

type Item = { type: string };
type QuoteStep = { items: Item[] };

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const THREE_RUNE_BLOCK_PREMIUM = 60;

const basePremiumOf = (type: string): number => {
  const basePremium = BASE_PREMIUMS[type];
  if (basePremium === undefined) throw new Error(`Unknown item type: ${type}`);
  return basePremium;
};

const policyBasePremiumOf = (items: Item[]): number => {
  const runeCount = items.filter(({ type }) => type === "rune").length;
  if (runeCount === 3) return THREE_RUNE_BLOCK_PREMIUM;
  return items.reduce((sum, { type }) => sum + basePremiumOf(type), 0);
};

const FLOATING_POINT_TOLERANCE = 1e-9;

// round up in the MHPCO's favor; the tolerance absorbs floating-point noise (e.g. 60 * 0.1)
const roundUpInMHPCOsFavor = (amount: number): number =>
  Math.ceil(amount - FLOATING_POINT_TOLERANCE);

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const step = scenario.steps[0] as QuoteStep;
  const basePremium = policyBasePremiumOf(step.items);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  const premium = roundUpInMHPCOsFavor(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);
  return { results: [{ premium }] };
};

