export const runScenario = (scenario: Scenario): ScenarioResult => {
  let quotesSoFar = 0;
  const results = scenario.steps.map((rawStep) => {
    const step = rawStep as QuoteStep | ClaimStep;
    if (step.op === "claim") {
      return settleClaim(step, (scenario.steps[step.policy] as QuoteStep).items);
    }
    const premium = quotePremium(scenario.customer, step.items, quotesSoFar > 0);
    quotesSoFar++;
    return { premium };
  });
  return { results };
};

